// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address candidate) public {

        bool ok;
        bool ret;
        try c.approvedToLog(candidate) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        bool mapped = c.approvedLoggers(candidate);

        assertTrue(ok && (mapped == ret || mapped == false && ret == false));
    }
}
